//cellular noise
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 st = (2.0*fragCoord-iResolution.xy)/min(iResolution.y,iResolution.x);
    vec3 color = vec3(.0);
    vec2 point[4];
    point[0] = vec2(-0.6,-0.6);
    point[1] = vec2(0.6,-0.6);
    point[2] = vec2(-0.6,0.6);
    point[3] = vec2(0.6,0.6);

    float m_dist = 1.;
    for (int i = 0; i < 4; i++) {
        vec2 p = point[i];//0.5 + 0.5*sin(iTime + 6.2831*point[i]);
        float dist = distance(st, p)*1.0;
        m_dist = min(m_dist, dist);
    }
    color += m_dist;
    color += 1.-step(.025, m_dist); 
    fragColor = vec4(color,1.0);
}
